def find_length(string):
    n = len(string)
    current_diff = 0
    max_diff = 0
    for i in range(n):
        current_diff += (1 if string[i] == '0' else -1)
        if current_diff < 0:
            current_diff = 0
        max_diff = max(current_diff, max_diff)
    return max_diff if max_diff else 0

